// Фиктивный провайдер Responses API: отдаёт шаги сценария по одному на POST /responses
// и пишет каждый запрос в журнал.
import http from 'node:http';
import fs from 'node:fs';
const [port, scriptFile, journal] = process.argv.slice(2);
const steps = JSON.parse(fs.readFileSync(scriptFile, 'utf8'));
let n = 0;
const sse = (res, events) => {
  res.writeHead(200, { 'content-type': 'text/event-stream' });
  for (const e of events) res.write(`event: ${e.type}\ndata: ${JSON.stringify(e)}\n\n`);
  res.end();
};
http.createServer((req, res) => {
  let body = '';
  req.on('data', (d) => (body += d));
  req.on('end', () => {
    fs.appendFileSync(journal, JSON.stringify({ method: req.method, url: req.url, body: body.slice(0, 400000) }) + '\n');
    if (req.method === 'GET') { res.writeHead(200, { 'content-type': 'application/json' }); return res.end('{"object":"list","data":[],"models":[]}'); }
    if (!req.url.includes('responses')) { res.writeHead(404); return res.end(); }
    let items = steps[Math.min(n, steps.length - 1)];
    const sid = [...body.matchAll(/session ID (\d+)|\\?"session_id\\?":\s*(\d+)/g)].pop();
    if (sid) items = JSON.parse(JSON.stringify(items).replaceAll('__SID__', sid[1] ?? sid[2]));
    const id = 'resp-' + ++n;
    const ev = [{ type: 'response.created', response: { id } }];
    for (const it of items) ev.push({ type: 'response.output_item.done', item: it });
    ev.push({ type: 'response.completed', response: { id, usage: { input_tokens: 1, input_tokens_details: null, output_tokens: 1, output_tokens_details: null, total_tokens: 2 } } });
    sse(res, ev);
  });
}).listen(Number(port), '127.0.0.1', () => fs.appendFileSync(journal, '{"ready":true}\n'));

kit.hook.cjs:
// Хук стенда: пишет сырой вход целиком в файл из argv, блокирует на маркере.
const fs = require('fs');
let s = '';
process.stdin.on('data', (d) => (s += d));
process.stdin.on('end', () => {
  fs.appendFileSync(process.argv[2], JSON.stringify({ argv: process.argv.slice(3), env: { CODEX_HOME: process.env.CODEX_HOME, PWD: process.cwd() }, input: s }) + '\n');
  if (s.includes('ralph-stand-forbidden')) { process.stderr.write('blocked by stand hook'); process.exit(2); }
  process.exit(0);
});

