hookLayers.caseScript:
. "$D/common-h.sh"
# Проектный файл хуков Codex в дереве потребителя (стенд, не данные контура канона).
ARGS=("${BASE[@]}" "${HOOK[@]}"); pre() { mkdir -p "$C/.codex"; CJ projjson >"$C/.codex/hooks.json"; }

. "$D/common-h.sh"
# Проектный файл хуков Codex при проекте, объявленном недоверенным переопределением -c.
ARGS=("${BASE[@]}" "${HOOK[@]}" -c "projects={\"$C\"={trust_level=\"untrusted\"}}"); pre() { mkdir -p "$C/.codex"; CJ projjson >"$C/.codex/hooks.json"; }

. "$D/common-h.sh"
# Проектный файл хуков Codex без флага обхода доверия хукам.
ARGS=("${BASE[@]}" --enable hooks -c "$(hookreg "$OUT/hook.jsonl")"); pre() { mkdir -p "$C/.codex"; CJ projjson >"$C/.codex/hooks.json"; }

. "$D/common-h.sh"
# Файл хуков в доме Codex (CODEX_HOME стенда) рядом с нашим -c.
ARGS=("${BASE[@]}" "${HOOK[@]}"); pre() { CJ userjson >"$CODEX_HOME/hooks.json"; }
